from core import *

def papers():
 p=[]
 p.append(item('In 603,418, what value does the digit 3 represent?',3000,'The 3 is in the thousands column, so its value is 3 × 1000 = 3000. The zero holds the ten-thousands place.','DIG-01',[3,30,300,30000],check=3*1000))
 p.append(item('A machine adds 8 to its input, then doubles the result. What is its output for input 6?',28,'Do the operations in their stated order: 6 + 8 = 14, then 14 × 2 = 28. Doubling 6 first would use a different machine.','ALG-01',[20,22,40,96],check=(6+8)*2))
 p.append(item('A loaf is cut into 12 equal slices. Five are eaten and one is given away. What fraction of the loaf remains?','1/2','Six slices leave the loaf: 5 + 1 = 6. The other 6 of the original 12 slices remain, so the fraction is 6/12 = 1/2.','FRAC-01',['5/12','7/12','1/3','2/3'],check=str(F(12-5-1,12))))
 p.append(item('A film begins at 10:45 am and lasts 95 minutes. When does it finish?','12:20 pm','Split 95 minutes into 60 + 35. One hour after 10:45 is 11:45, and another 35 minutes takes the clock to 12:20 pm.','RATE-01',['11:40 am','12:10 pm','12:30 pm','1:20 pm']))
 p.append(item('The outline is a non-square rectangle. How many lines of reflection symmetry does it have?',2,'The vertical and horizontal lines through the centre each fold the rectangle onto itself. A diagonal does not, because the adjacent side lengths are different.','GEO-04',[0,1,4,8],figure=polygon([(75,50),(345,50),(345,180),(75,180)])))
 p.append(item('The chart shows books borrowed on four days. How many more books were borrowed on Thursday than on Tuesday?',7,'Read the two labelled bars: Thursday has 19 and Tuesday has 12. The difference, rather than the total, is 19 − 12 = 7 books.','DATA-03',[5,12,19,31],check=19-12,figure=bars([15,12,17,19],['Mon','Tue','Wed','Thu'])))
 p.append(item('A rectangular garden is 9 m long and 4 m wide. A gate occupies 2 m of its boundary. How many metres of fencing are needed?',24,'The complete perimeter is 2 × (9 + 4) = 26 m. The gate replaces 2 m of fencing, leaving 26 − 2 = 24 m.','GEO-01',[11,13,26,34],check=2*(9+4)-2))
 p.append(item('A notebook costs $2.40. What change should be received when three notebooks are paid for with $10?','$2.80','Three notebooks cost 3 × $2.40 = $7.20. Subtract that cost from the amount paid: $10.00 − $7.20 = $2.80.','DIG-01',['$2.40','$3.20','$5.20','$7.60']))
 p.append(item('A ribbon is 1.8 m long. A piece 65 cm long is cut off. How many centimetres remain?',115,'Put both lengths in centimetres: 1.8 m = 180 cm. Then subtract the cut piece: 180 − 65 = 115 cm.','RATE-01',[1.15,65,135,175],check=180-65))
 p.append(item('What fraction of the equal squares in the grid are shaded?','3/8','There are 4 × 2 = 8 equal squares and 3 are shaded. A fraction compares the shaded count with all equal pieces, giving 3/8.','FRAC-04',['1/4','3/5','1/2','5/8'],check=str(F(3,8)),figure=grid(4,2,[(0,0),(1,0),(3,1)])))
 p.append(item('At a camp, 18 children canoe, 15 climb, and 7 do both. Every child does at least one of these activities. How many children are there?',26,'Adding 18 and 15 counts the seven children who do both twice. Remove one extra copy of that overlap: 18 + 15 − 7 = 26.','COUNT-04',[19,25,33,40],check=18+15-7))
 p.append(item('A number is tripled, then 11 is subtracted. The result is 40. What was the number?',17,'Undo the final subtraction first: 40 + 11 = 51. Undo tripling by dividing by 3: 51 ÷ 3 = 17. Check 3 × 17 − 11 = 40.','ALG-04',[9,13,15,19],check=(40+11)//3))
 p.append(item('The pages of a booklet are numbered 1 to 35. How many times is the digit 3 printed in those page numbers?',10,'The units column contains 3 on pages 3, 13, 23 and 33: four copies. Pages 30–35 contribute six tens-column copies. The total is 4 + 6 = 10; page 33 correctly contributes twice.','DIG-03',[8,9,11,13],check=''.join(map(str,range(1,36))).count('3')))
 p.append(item('Four quiz scores have a mean of 16. Three of the scores are 12, 17 and 19. What is the fourth score?',16,'The mean tells us the total: 4 × 16 = 64. The known scores sum to 12 + 17 + 19 = 48. The missing score is 64 − 48 = 16.','DATA-02',[12,14,18,20],check=4*16-12-17-19))
 p.append(item('In triangle ABC, angle A is 46° and angle B is twice angle A. What is angle C?',42,'Angle B is 2 × 46° = 92°. The three interior angles total 180°, so C = 180° − 46° − 92° = 42°.','GEO-03',[38,46,88,92],check=180-3*46,figure=polygon([(65,190),(350,190),(180,40)],[(50,212,'A'),(367,212,'B'),(180,26,'C')],fill='#eff5f7')))
 p.append(item('A straight fence has posts at both ends and at every 3 m between them. The fence is 27 m long. How many posts are there?',10,'The fence contains 27 ÷ 3 = 9 equal gaps. A row with both endpoints included has one more post than gaps, so it needs 10 posts.','RATE-01',[8,9,11,12],check=27//3+1))
 p.append(item('Two ordinary six-sided dice are rolled. How many ordered outcomes have a total of 9?',4,'List the first die and the matching second die: (3,6), (4,5), (5,4), (6,3). Each is a different ordered outcome, so there are 4.','DATA-01',[2,3,5,6],check=sum(a+b==9 for a,b in product(range(1,7),repeat=2))))
 p.append(item('A box contains red and blue counters in the ratio 3:5. There are 40 counters altogether. How many red counters must be added to make the two colours equally numerous?',10,'Eight ratio parts total 40, so each part is 5. There are 15 red and 25 blue counters. Add 25 − 15 = 10 red counters; adding changes the total but not the blue count.','FRAC-02',[5,8,15,20],check=40//8*(5-3)))
 p.append(item('A 7-by-5 rectangle of unit tiles has a one-tile-wide border shaded all the way around. How many tiles are shaded?',20,'Subtract the unshaded interior from the whole. The whole has 7 × 5 = 35 tiles; removing one row or column from each side leaves 5 × 3 = 15 inside. Thus 35 − 15 = 20 are shaded.','GEO-02',[18,22,24,35],check=7*5-5*3,figure=grid(7,5,[(x,y) for x in range(7) for y in range(5) if x in [0,6] or y in [0,4]])))
 p.append(item('A walker covers 3 km in 36 minutes, rests for 12 minutes, then covers another 2 km in 24 minutes. What is the average speed for the whole outing, including the rest?','25/6 km/h','The full distance is 5 km. The full time is 36 + 12 + 24 = 72 minutes = 6/5 hour. Average speed is 5 ÷ (6/5) = 25/6 km/h. Including the rest is essential.','RATE-03',['4 km/h','5 km/h','6 km/h','25/3 km/h']))
 p.append(item('A school sells 32 tickets. Adult tickets cost $9 and child tickets $5. The total collected is $220. How many adult tickets were sold?',15,'If all 32 tickets were child tickets, the total would be $160. Each adult ticket adds $4. The extra $60 therefore comes from 60 ÷ 4 = 15 adult tickets. Check: 15 × 9 + 17 × 5 = 220.','ALG-03',[12,14,16,17],check=(220-32*5)//4))
 p.append(item('A 3 cm by 2 cm rectangle is removed from the middle of one 10 cm side of a 10 cm by 7 cm rectangle, making an inward notch 2 cm deep. What is the new perimeter?',38,'The original perimeter is 34 cm. The notch removes 3 cm of boundary but adds another 3 cm across its back, so these cancel. Its two new sides add 2 + 2 = 4 cm, giving 38 cm.','GEO-01',[28,34,36,40],check=2*(10+7)+2*2,figure=polygon([(55,40),(145,40),(145,90),(220,90),(220,40),(345,40),(345,210),(55,210)],[(200,232,'10 cm'),(375,130,'7 cm'),(180,113,'3 cm'),(245,72,'2 cm')])) )
 p.append(item('What is the final digit of 7²⁰² × 3²⁰³?',3,'Powers of 7 end in 7,9,3,1, so exponent 202 selects 9. Powers of 3 end in 3,9,7,1, so exponent 203 selects 7. The product ends like 9 × 7 = 63, hence 3.','DIV-05',[1,7,9,0],check=(pow(7,202,10)*pow(3,203,10))%10))
 p.append(item('Two runners start together on a circular track, running in the same direction. One completes a lap in 4 minutes and the other in 6 minutes. After how many minutes does the faster runner first catch the slower runner again?',12,'The faster runner gains 1/4 − 1/6 = 1/12 of a lap per minute. Catching up requires one full lap of gain, which takes 12 minutes. This is a relative-speed question.','RATE-04',[2,8,10,24],check=int(1/(F(1,4)-F(1,6)))))
 p.append(item('Three different digits from 0, 1, 2, 3 and 4 form a three-digit number. How many such numbers are both even and divisible by 3?',13,'The digit sets with sum divisible by 3 are {0,1,2}, {0,2,4}, {1,2,3}, {2,3,4}. Their valid even numbers number 3, 4, 2 and 4 respectively. Add: 3 + 4 + 2 + 4 = 13. Check the leading digit is never zero.','COUNT-06',[10,12,14,16],check=sum(a!=0 and c%2==0 and (a+b+c)%3==0 for a,b,c in permutations(range(5),3))))
 p.append(item('Find the smallest three-digit number that leaves remainder 3 when divided by 7, remainder 5 when divided by 9, and remainder 1 when divided by 5.',311,'Numbers meeting the first two conditions are 59 + 63k: 59 works, and the common repeat interval is 7 × 9 = 63. To have remainder 1 modulo 5, 4 + 3k must leave 1, so k leaves 4 modulo 5. The first suitable nonnegative k is 4, giving 59 + 252 = 311.','DIV-03',check=next(n for n in range(100,1000) if n%7==3 and n%9==5 and n%5==1)))
 p.append(item('A 2-by-9 board is tiled completely with 1-by-2 dominoes. Exactly three dominoes are vertical. How many tilings are possible?',20,'The three vertical dominoes each occupy one full column. The remaining six columns are filled by three pairs of horizontal dominoes, each pair occupying two columns. Arrange these six pieces in a row: three single columns and three double columns. Choose the three positions of the double columns: 6 choose 3 = 20.','COUNT-02',check=math.comb(6,3),figure=grid(9,2)))
 p.append(item('How many different triangles have three distinct positive whole-number side lengths and perimeter 30? Rotations and reflections count as the same triangle.',12,'Write the lengths a < b < c. The triangle inequality gives c < 15, while distinctness and total 30 give c ≥ 11. For c = 11,12,13,14, the possible (a,b) pairs number 1,2,4,5. They total 12. For example, c = 14 requires a + b = 16 with 2 < a < 8, giving five pairs.','COUNT-06',check=sum(sum(z)==30 and z[0]+z[1]>z[2] for z in combinations(range(1,30),3))))
 cells=[(x,y) for x in range(5) for y in range(5) if (x+y)%2==0]
 p.append(item('A 5-by-5 checkerboard has dark squares in all four corners. Two identical counters are placed on different dark squares. They must share neither a row nor a column. How many placements are possible?',56,'There are 13 dark squares, so initially choose any two in 13 × 12 ÷ 2 = 78 ways. Row dark counts are 3,2,3,2,3, giving 3 + 1 + 3 + 1 + 3 = 11 same-row pairs. Columns exclude another 11. A pair of distinct squares cannot share both row and column, so 78 − 22 = 56.','COUNT-04',check=sum(a[0]!=b[0] and a[1]!=b[1] for a,b in combinations(cells,2)),figure=grid(5,5,cells)))
 p.append(item('How many four-digit numbers have four different digits chosen from 1 to 9, digit sum 22, contain the digit 5, and are divisible by 11?',24,'For divisibility by 11, the sums in alternating positions differ by a multiple of 11. Their total is 22, and the possible sums force both to be 11. The 5 must pair with 6. The other pair is 2+9, 3+8 or 4+7. Choose that pair (3 ways), choose which alternating positions contain 5 and 6 (2), then order each pair (2 × 2): 24.','DIG-05',check=sum(sum(z)==22 and (z[0]+z[2]-z[1]-z[3])%11==0 and 5 in z for z in permutations(range(1,10),4))))
 one=paper('amc',1,p)
 p=[]
 p.append(item('Which number is halfway between 38 and 56?',47,'The gap is 56 − 38 = 18. Move half that gap, 9, from 38: 38 + 9 = 47. It is also 9 below 56.','ALG-02',[44,46,48,49],check=(38+56)//2))
 p.append(item('Six packets each hold eight crayons. Nine crayons are used. How many unused crayons remain?',39,'First count all crayons: 6 × 8 = 48. Then remove the nine used crayons: 48 − 9 = 39.','DIG-01',[33,37,41,57],check=6*8-9))
 p.append(item('A bottle holds 750 mL. How many full bottles are needed to hold exactly 3 litres?',4,'Three litres is 3000 mL. Since 4 × 750 = 3000, exactly four full bottles hold the required amount.','RATE-01',[3,5,6,8],check=3000//750))
 p.append(item('The table shows points won in three rounds. Which player has the greatest total?','B','Add each row: A has 8+7+9=24, B has 6+10+10=26, C has 9+8+8=25, D has 7+7+10=24. B has the largest total.','DATA-03',['A','C','D','A and D'],figure=table_diagram([['A',8,7,9],['B',6,10,10],['C',9,8,8],['D',7,7,10]],['Player','R1','R2','R3'])))
 p.append(item('A square has perimeter 36 cm. What is its area in square centimetres?',81,'Four equal sides total 36 cm, so each side is 9 cm. The area is side × side = 9 × 9 = 81 cm².','GEO-02',[9,18,36,72],check=(36//4)**2))
 p.append(item('What is three quarters of 28?',21,'Divide 28 into four equal parts: 28 ÷ 4 = 7. Take three of those parts: 3 × 7 = 21.','FRAC-01',[7,14,18,24],check=28//4*3))
 p.append(item('The equally spaced marks on the number line show 4, a blank, 16, another blank, and 28. What number belongs at the first blank?',10,'The gap from 4 to 16 contains two equal steps, so one step is (16 − 4) ÷ 2 = 6. The first blank is 4 + 6 = 10.','SEQ-01',[6,8,12,14],check=4+(16-4)//2,figure=number_line([4,'?',16,'',28])))
 p.append(item('A shop discounts a $30 game by $6. What percentage of the original price is the discount?',20,'Compare the discount with the original price: 6/30 = 1/5. One fifth is 20%, so the discount is 20%.','FRAC-03',[6,15,24,25],check=6*100//30))
 p.append(item('How many edges does a triangular prism have?',9,'Each triangular end has 3 edges, giving 6. Three more edges connect matching vertices of the two ends. In total there are 6 + 3 = 9 edges.','SOLID-03',[5,6,8,12],figure=svg('<path d="M80,180L170,35L235,180Z M190,205L280,60L345,205Z M80,180L190,205 M170,35L280,60 M235,180L345,205" fill="none"/>',label='Triangular prism with both triangular ends shown')))
 p.append(item('A jar contains only 20-cent and 50-cent coins. Three of each kind are taken out. What is the total value taken out?','$2.10','The three 20-cent coins total 60 cents and the three 50-cent coins total 150 cents. Together that is 210 cents, or $2.10.','DIG-01',['$1.50','$1.80','$2.40','$3.00']))
 p.append(item('When a whole number is divided by 8, the quotient is 12 and the remainder is 5. What is the number?',101,'Rebuild the number from full groups and leftovers: 8 × 12 + 5 = 101. The remainder 5 is smaller than the divisor 8, as required.','DIV-03',[91,96,100,105],check=8*12+5))
 p.append(item('Each table seats four people. When tables are joined end to end in one straight row, each join removes two seats. How many people can sit at six joined tables?',14,'Six separate tables provide 24 seats. Joining six tables in a row makes five joins, each removing two seats. Therefore 24 − 10 = 14 seats remain.','GEO-01',[12,16,18,24],check=6*4-(6-1)*2))
 p.append(item('A bag has 4 red, 3 blue and 5 green counters. One counter is selected at random. What is the probability that it is not green?','7/12','There are 12 counters in all. The non-green counters are the 4 red and 3 blue, so there are 7 favourable counters. The probability is 7/12.','DATA-01',['5/12','1/2','2/3','7/5'],check=str(F(4+3,4+3+5))))
 p.append(item('Two bells ring together at noon. They ring every 9 minutes and every 12 minutes. How many times do they ring together strictly after noon and no later than 2 pm?',3,'Their common interval is lcm(9,12)=36 minutes. Within the next 120 minutes, common rings occur at minutes 36,72,108. Noon is excluded and the next ring at 144 is too late.','DIV-02',[2,4,5,10],check=120//math.lcm(9,12)))
 p.append(item('The shaded triangle has a base of 12 cm and a perpendicular height of 7 cm. What is its area?', '42 cm²','Triangle area is half base × perpendicular height. Thus 12 × 7 ÷ 2 = 42 cm². The dashed perpendicular, not a sloping side, supplies the height.','GEO-02',['19 cm²','38 cm²','84 cm²','96 cm²'],figure=polygon([(40,195),(360,195),(140,35)],[(205,225,'12 cm'),(175,112,'7 cm')],extra='<path d="M140,35V195" stroke-dasharray="5 5"/><path d="M140,183H152V195" fill="none"/>')))
 p.append(item('A sequence is made by repeatedly adding 4, starting with 7. What is its 20th term?',83,'The first term already occupies position 1. Reaching term 20 requires 19 additions of 4, so the term is 7 + 19 × 4 = 83.','SEQ-01',[76,80,84,87],check=7+19*4))
 p.append(item('A two-digit number has digit sum 11. Reversing its digits makes a number 27 smaller. What is the original number?',74,'Let the tens digit exceed the units digit by d. Reversing changes the value by 9d, so d=27÷9=3. The two digits sum to 11 and differ by 3, giving 7 and 4. The number is 74.','DIG-05',[47,65,83,92],check=next(n for n in range(10,100) if sum(map(int,str(n)))==11 and n-int(str(n)[::-1])==27)))
 p.append(item('A swimmer completes 250 m in 5 minutes at a constant speed. At the same speed, how long does 900 m take?', '18 minutes','The swimmer covers 250 ÷ 5 = 50 metres each minute. Therefore 900 ÷ 50 = 18 minutes are needed. Keep metres and minutes consistent.','RATE-03',['15 minutes','16 minutes','20 minutes','22 minutes']))
 p.append(item('In a class, the ratio of students wearing glasses to those not wearing glasses is 2:7. Six students wear glasses. How many students are in the class?',27,'Two ratio parts equal 6 students, so a part is 3. The whole class has 2+7=9 parts: 9 × 3 = 27.','FRAC-02',[21,24,28,36],check=(2+7)*(6//2)))
 p.append(item('A square sheet is folded in half vertically and then in half horizontally. A small hole is punched strictly inside the folded square, away from every fold and outer edge. How many holes appear when it is unfolded?',4,'Each fold doubles the number of paper layers. There are four layers at an interior point after two folds, so the punch makes four separate holes on unfolding. Staying away from folds prevents holes from joining.','SPATIAL-03',[1,2,3,8]))
 p.append(item('A water tank starts one quarter full. Adding 18 litres makes it five eighths full. What is its capacity in litres?',48,'The added fraction is 5/8 − 1/4 = 3/8 of the tank. If 3/8 equals 18 litres, one eighth equals 6 litres and the whole tank holds 8 × 6 = 48 litres.','FRAC-01',[24,32,40,72],check=int(F(18)/(F(5,8)-F(1,4)))))
 p.append(item('On the grid, move only right or up along grid lines from S to T. How many routes avoid the crossed vertex?',6,'The grid is four steps across and two up, so all routes number 6 choose 2 = 15. A route through (2,1) has 3 ways to reach that point and 3 ways to finish, giving 9 forbidden routes. Subtract: 15 − 9 = 6.','SPATIAL-01',[9,12,15,24],check=count_routes(4,2,[(2,1)]),figure=routes(4,2,[(2,1)])))
 p.append(item('Four friends each shake hands once with every other friend. They then each shake hands once with a fifth person. How many handshakes occur altogether?',10,'Among the original four friends there are 4 × 3 ÷ 2 = 6 handshakes. The fifth person adds one with each of the four, so 6 + 4 = 10.','COUNT-05',[6,8,12,20],check=math.comb(4,2)+4))
 p.append(item('A cuboid is 4 cubes wide, 3 cubes deep and 5 cubes high. Its top face only is painted. How many unit cubes have no paint?',48,'There are 4 × 3 × 5 = 60 cubes. Only the 4 × 3 = 12 cubes in the top layer receive paint. Hence 60 − 12 = 48 cubes have none.','SOLID-02',[12,36,42,60],check=4*3*(5-1),figure=cuboid(4,3,5)))
 p.append(item('A positive whole number has exactly three positive divisors, and is less than 100. What is the largest possible number?',49,'Exactly three divisors means the number is p² for a prime p: the divisors are 1,p,p². The largest prime whose square is less than 100 is 7, giving 49. Although 81 is a square, its base 9 is not prime and it has five divisors.','DIV-01',[25,64,81,97],check=max(n for n in range(1,100) if len(divisors(n))==3)))
 p.append(item('How many three-digit numbers have digits that strictly increase from left to right and have a digit sum of 15?',8,'An increasing three-digit number cannot contain 0. Choose a<b<c from 1 to 9 with sum 15. The triples are (1,5,9),(1,6,8),(2,4,9),(2,5,8),(2,6,7),(3,4,8),(3,5,7),(4,5,6). Each triple gives exactly one number, so there are 8.','DIG-02',check=sum(sum(z)==15 for z in combinations(range(1,10),3))))
 p.append(item('Five switches start OFF. A move chooses exactly two different switches and reverses their states. How many different final ON/OFF arrangements can be reached after any number of moves, including zero moves?',16,'A move changes the number of ON switches by −2, 0 or 2, so only even ON counts are reachable. Every chosen even-sized set can be made ON by pairing its switches and flipping each pair once. Count sets of sizes 0,2,4: 1 + 10 + 5 = 16.','DIV-04',check=sum(math.comb(5,k) for k in [0,2,4])))
 p.append(item('A rectangle has whole-number side lengths, area 180 cm² and perimeter less than 60 cm. How many different rectangles are possible? Turning a rectangle does not make a new one.',3,'List factor pairs with the shorter side first: (1,180),(2,90),(3,60),(4,45),(5,36),(6,30),(9,20),(10,18),(12,15). Perimeter below 60 means the pair sum is below 30. Only (9,20),(10,18),(12,15) qualify, giving 3.','GEO-05',check=sum(180%a==0 and a<=180//a and 2*(a+180//a)<60 for a in range(1,181))))
 p.append(item('Place one counter in each row of a 4-by-4 board. No two counters may share a column, and no counter may occupy the main diagonal from top left to bottom right. How many placements are possible?',9,'Start with 4!=24 column assignments. Inclusion–exclusion removes those using a forbidden diagonal square: 24 − 4×6 + 6×2 − 4×1 + 1 = 9. The intersections fix two, three or four specified rows, which explains the successive terms.','COUNT-04',check=sum(all(i!=v for i,v in enumerate(z)) for z in permutations(range(4))),figure=grid(4,4,[(i,i) for i in range(4)])))
 p.append(item('A box contains 1-cent, 5-cent and 10-cent coins, with at least one of each kind. There are exactly 20 coins worth 100 cents. There are more 5-cent coins than 1-cent coins. How many 5-cent coins are there?',11,'Let a,b,c count the 1-,5-,10-cent coins. Subtract a+b+c=20 from a+5b+10c=100: 4b+9c=80. Modulo 4, c must be a positive multiple of 4. The only possible triples are (5,11,4) and (10,2,8). Only the first has b>a, so there are 11 five-cent coins. Check: 5+55+40=100 cents.','LOGIC-02'))
 assert [(a,b,c) for a in range(1,20) for b in range(a+1,20) for c in range(1,20) if a+b+c==20 and a+5*b+10*c==100]==[(5,11,4)]
 return [one,paper('amc',2,p)]

if __name__=='__main__':write_papers(papers(),'../../rebuild/content')
